/* Clinical transfer views. Deliberately schematic, no patient dose or tumor-response solver. */
(()=>{'use strict';const m=location.pathname.match(/phase([34])\.html$/);if(!m)return;
const phase=+m[1],before=document.querySelector('.phase-next');if(!before)return;
const section=document.createElement('section');section.className='clinical-bridge';section.id=phase===3?'doseBridge':'seriesBridge';
const x=phase===3?'<p class="bridge-kicker">ZWISCHENANSICHT 03A · PHYSIK → PRAXIS</p><h2>Von Elektronenspuren zur Energiedosis</h2><p>Die <strong>absorbierte Dosis</strong> beschreibt Energie pro Masse. <strong>1 Gray (Gy) = 1 Joule pro Kilogramm.</strong> Im Gewebe führen Sekundärelektronen zu lokaler Energiedeposition. Die Tiefendosis hängt unter anderem von Energie, Feld, Abstand und Material ab.</p><div class="bridge-grid"><div><svg id="depthChart" viewBox="0 0 670 330" role="img" aria-label="Schematische relative Tiefendosiskurve mit Aufbaubereich und Maximum"></svg><p class="bridge-foot">Prinzipdarstellung, keine Messkurve und keine klinisch gültige Dosisberechnung.</p></div><div class="bridge-controls"><label for="depth">Tiefe im Gewebe: <output id="depthLabel">1,5 cm</output></label><input id="depth" type="range" min="0" max="8" step=".5" value="1.5"><label class="switch-row"><input id="bolus" type="checkbox"> Bolus im Lehrmodell hinzufügen</label><p id="depthExplanation"></p><p class="bridge-take"><strong>MTR-Transfer:</strong> Bolus und Lagerungshilfen genau wie geplant anwenden. Eine Maske kann je nach Material und Aufbau die Oberflächendosis beeinflussen; sie ist kein pauschaler Ersatz für einen geplanten Bolus.</p></div></div><a class="bridge-next" href="phase4.html">Weiter zur DNA- und Zellwirkung →</a>':
'<p class="bridge-kicker">ABSCHLUSS · ZURÜCK ZUM PATIENTEN</p><h2>Warum die Bestrahlung in Fraktionen erfolgt</h2><p>Jede Fraktion erzeugt Schäden in Tumor- und Normalgewebe. <strong>Reparatur zwischen den Fraktionen</strong> ist ein wichtiger Grund für die Aufteilung der Therapie. Der zeitliche Verlauf von Zellwirkung und Nebenwirkungen ist nicht mit dem Moment der Bestrahlung identisch.</p><div class="bridge-grid"><div><svg id="seriesChart" viewBox="0 0 670 300" role="img" aria-label="Fünf schematische Behandlungstage, Reparaturphasen zwischen den Fraktionen"></svg><p class="bridge-foot">Fünf Tage dienen nur als visuelles Beispiel. Reale Einzeldosen, Fraktionszahlen und Therapiedauern sind verordnungsabhängig.</p></div><div class="bridge-controls"><label for="fractions">Behandlungstag im Beispiel: <output id="fractionLabel">1 von 5</output></label><input type="range" id="fractions" min="1" max="5" step="1" value="1"><p id="fractionExplanation"></p><p class="bridge-take"><strong>MTR-Transfer:</strong> Freigegebenen Plan und verordnete Fraktion beachten, Lagerung reproduzieren und auf verzögert auftretende Nebenwirkungen achten. Unterbrechungen und Planänderungen ärztlich klären.</p></div></div><a class="bridge-next" href="index.html">Zur Phasenübersicht →</a>';
section.innerHTML=x;before.insertAdjacentElement('beforebegin',section);
const $=id=>document.getElementById(id),n=v=>Number(v).toFixed(2);
if(phase===3){
 const f=(z,b)=>{const peak=b?.25:1.5,surface=b?.74:.35;return z<peak?surface+(1-surface)*z/peak:Math.exp(-(z-peak)/(b?10:12));};
 const X=z=>65+z/8*545,Y=v=>262-v*193;
 function draw(){const bolus=$('bolus').checked,z=+$('depth').value;const p=[];for(let i=0;i<=120;i++){const d=i*8/120;p.push((i?'L':'M')+n(X(d))+' '+n(Y(f(d,bolus))));}
 const v=f(z,bolus);
 $('depthChart').innerHTML=`<rect x="0" y="0" width="670" height="330" fill="#f5fbfd" rx="9"/><path d="M65 40V262H620" stroke="#507389" stroke-width="2" fill="none"/><path d="M65 69H620M65 166H620" stroke="#cedee5" stroke-dasharray="5 6"/><text x="75" y="32" font-size="17" fill="#24637e">Relative Tiefendosis (Schema)</text><text x="65" y="293" font-size="16" fill="#456b7e">Haut</text><text x="550" y="293" font-size="16" fill="#456b7e">Tiefe</text><text x="20" y="72" font-size="15" fill="#456b7e">100 %</text><path d="${p.join('')}" stroke="${bolus?'#e94c0a':'#0a87aa'}" stroke-width="5" fill="none"/><path d="M${n(X(z))} 262V${n(Y(v))}" stroke="#607e8b" stroke-dasharray="5 6" stroke-width="2"/><circle cx="${n(X(z))}" cy="${n(Y(v))}" r="8" fill="${bolus?'#e94c0a':'#0a87aa'}"/><text x="280" y="312" font-size="16" fill="#24637e">${bolus?'Bolus: Maximum oberflächennäher':'Aufbaueffekt: Dosismaximum in der Tiefe'}</text>`;
 $('depthLabel').textContent=String(z).replace('.',',')+' cm';
 $('depthExplanation').textContent=(z< (bolus?.25:1.5)?'Du befindest dich im schematischen Aufbaubereich.':'Du befindest dich hinter dem schematischen Dosismaximum.')+' Der markierte Kurvenwert ist relativ, nicht die verordnete Patientendosis.';}
 $('depth').oninput=draw;$('bolus').onchange=draw;draw();
}else{
 const X=i=>76+(i-1)*129;function draw(){const at=+$('fractions').value;let h='<rect width="670" height="300" fill="#f5fbfd" rx="9"/><text x="28" y="35" fill="#226f8b" font-size="19">Fraktion und Zwischenzeit · Schema</text><path d="M50 226H628" stroke="#95adbc" stroke-width="2"/>';
 for(let i=1;i<=5;i++){const x=X(i),active=i<=at;h+=`<rect x="${x-37}" y="86" width="74" height="125" rx="7" fill="${active?'#e3f4f8':'#edf1f3'}" stroke="${i===at?'#0a87aa':'#bfd0d9'}" stroke-width="${i===at?3:1}"/><path d="M${x-17} 117H${x+17}M${x} 100V134" stroke="${active?'#e94c0a':'#9eb1ba'}" stroke-width="5"/><text x="${x}" y="171" text-anchor="middle" fill="#244b5a" font-size="16">Fx ${i}</text><text x="${x}" y="249" text-anchor="middle" fill="#45687a" font-size="16">Tag ${i}</text>`;
 if(i<5)h+=`<path d="M${x+40} 143H${x+86}" stroke="#7191a2" stroke-dasharray="5 5" stroke-width="3"/><text x="${x+64}" y="198" text-anchor="middle" fill="#557886" font-size="14">Reparatur</text>`;
 }
 h+='<text x="320" y="280" text-anchor="middle" font-size="16" fill="#557886">Wirkung und Gewebereaktionen entwickeln sich zeitlich verzögert.</text>';
 $('seriesChart').innerHTML=h;$('fractionLabel').textContent=at+' von 5';
 $('fractionExplanation').textContent=at===1?'Nach der ersten Fraktion beginnen zelluläre Reaktionen und Reparaturprozesse.':at<5?'Zwischen den Behandlungstagen laufen unter anderem Reparaturprozesse. Das Ausmaß ist gewebe- und zeitabhängig.':'Die Serie ist im Beispiel abgeschlossen; biologische Wirkungen und mögliche Nebenwirkungen können zeitlich verzögert auftreten.';}
 $('fractions').oninput=draw;draw();
}
})();